<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api/client'
import type { ComponentDescriptor, ComposerStage, Profile, ProfileComposerCatalog } from '../api/contracts'
import { useProfileDraft } from '../composables/useProfileDraft'
const router = useRouter(), { draft, updateStage, toggleChecker } = useProfileDraft()
const catalog = ref<ProfileComposerCatalog | null>(null), profiles = ref<Profile[]>([]), error = ref(''), loading = ref(true)
const sections: Array<{ id: ComposerStage; title: string; detail: string }> = [{ id: 'source', title: 'Source / 需求来源', detail: '决定任务从何处进入受控执行链。' }, { id: 'compiler', title: 'Spec Compiler / 规格编译', detail: '把需求转换为可验收的 Spec 与 Acceptance。' }, { id: 'maker', title: 'Maker / 生成器', detail: '在 Profile Policy 约束下生成制品。' }, { id: 'checker', title: 'Checkers / Harness 约束', detail: '承载计算型、反馈型与部分推理型约束判定。' }, { id: 'delivery', title: 'Delivery / 交付', detail: '决定制品的本地保存或受控外部交付。' }]
const items = (stage: ComposerStage) => catalog.value?.stages[stage] || []
const configFields = (item: ComponentDescriptor) => Object.keys((((item.config_schema || {}) as { properties?: Record<string, unknown> }).properties) || {})
const capabilities = (item: ComponentDescriptor) => Object.entries(item.capabilities).filter(([, allowed]) => allowed).map(([name]) => name).join(' · ') || '离线本地'
const references = (stage: ComposerStage, id: string) => profiles.value.filter(profile => stage === 'source' ? profile.source === id : stage === 'compiler' ? profile.compiler === id : stage === 'maker' ? profile.maker === id : stage === 'checker' ? profile.checkers?.includes(id) : profile.delivery === id).map(profile => profile.ref || profile.id)
const current = (stage: ComposerStage, id: string) => stage === 'source' ? draft.source.name === id : stage === 'compiler' ? draft.compiler === id : stage === 'maker' ? draft.maker === id : stage === 'checker' ? draft.checkers.includes(id) : draft.delivery === id
function apply(stage: ComposerStage, id: string) { if (stage === 'checker') { if (!draft.checkers.includes(id)) toggleChecker(id) } else updateStage(stage, id); router.push('/profile-composer/form') }
async function load() { loading.value = true; error.value = ''; try { const [catalogResponse, profileResponse] = await Promise.all([api.profileComposerCatalog(), api.profiles()]); catalog.value = catalogResponse.catalog; profiles.value = profileResponse.profiles.filter(item => item.valid) } catch (e) { error.value = e instanceof Error ? e.message : '无法读取组件配置中心' } finally { loading.value = false } }
onMounted(load)
</script>
<template><section class="page component-registry"><div class="page-heading"><div><p class="eyebrow">PROFILE COMPONENT REGISTRY</p><h1>组件配置中心</h1><p>组件目录是 Composer 下拉框与画布的唯一来源。这里显示服务端已注册组件、可安全配置字段、权限风险与正式 Profile 引用关系。</p></div><RouterLink class="primary-button" to="/profiles">查看 Profile 库</RouterLink></div><p v-if="error" class="data-warning">⚠ {{ error }}</p><p v-if="loading" class="empty-state">正在读取服务端组件目录…</p><template v-else-if="catalog"><section class="workspace-panel registry-intro"><div><h2>组件与配置的边界</h2><p>已注册组件会立即出现在下拉编排和画布组件区；“应用到草稿”只修改当前未保存 Profile Draft。Source 与 GitHub Workflow 的非敏感字段可在编排页配置；Maker 凭据、插件代码和全局运行时配置不会暴露给浏览器。</p></div><button disabled title="插件注册 API 尚未开放，避免浏览器直接写入可执行组件">+ 添加组件（暂未开放）</button></section><section v-for="section in sections" :key="section.id" class="registry-section"><header><div><p>{{ section.id.toUpperCase() }}</p><h2>{{ section.title }}</h2><span>{{ section.detail }}</span></div><small>{{ items(section.id).length }} 个已注册</small></header><div class="component-grid"><article v-for="item in items(section.id)" :key="item.id" class="workspace-panel component-card"><div class="component-head"><div><span :class="current(section.id, item.id) ? 'selected-chip' : 'passed'">{{ current(section.id, item.id) ? '草稿已选择' : '已注册' }}</span><h3>{{ item.label }}</h3></div><span v-if="item.experimental" class="experiment-chip">实验性</span></div><p>{{ item.description }}</p><dl><div><dt>能力</dt><dd :class="{ risk: capabilities(item) !== '离线本地' }">{{ capabilities(item) }}</dd></div><div><dt>可配置字段</dt><dd>{{ configFields(item).length ? configFields(item).join('、') : '当前无 Profile 级公开字段' }}</dd></div><div><dt>正式 Profile 引用</dt><dd>{{ references(section.id, item.id).length ? references(section.id, item.id).join('、') : '暂无' }}</dd></div></dl><footer><button class="quiet-button" @click="apply(section.id, item.id)">{{ section.id === 'checker' && current(section.id, item.id) ? '已在草稿中' : '应用到草稿并配置' }}</button><button disabled title="新增组件需要受控插件注册、版本和安全审查">+ 添加同类组件</button></footer></article></div></section><section class="workspace-panel registry-boundary"><h2>暂未开放的操作</h2><ul><li>从浏览器新增 Adapter、Compiler、Maker、Checker 或 Delivery 插件。</li><li>在浏览器中填写 API Key、Token、密码、SSH 私钥或其他凭据。</li><li>把组件草稿直接注册为可执行生产组件。</li></ul><p>这些按钮保持置灰，待补齐插件签名、版本化、审计、RBAC 与受控凭据注入后再开放。</p></section></template></section></template>
<style scoped>.registry-intro{display:flex;justify-content:space-between;gap:18px;align-items:center}.registry-intro h2,.registry-section h2{margin:0;font-size:15px}.registry-intro p,.registry-section header span{margin:7px 0 0;color:var(--muted);font-size:12px}.registry-intro button,.component-card footer button[disabled]{border:1px solid var(--line);border-radius:8px;background:transparent;padding:9px;color:var(--soft);cursor:not-allowed}.registry-section{margin-top:22px}.registry-section>header{display:flex;justify-content:space-between;gap:15px;margin-bottom:10px}.registry-section header p{margin:0 0 5px;color:var(--violet);font-size:10px;font-weight:800;letter-spacing:.12em}.registry-section header small{color:var(--soft);font-size:11px}.component-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.component-card{display:flex;flex-direction:column}.component-head{display:flex;justify-content:space-between;gap:10px}.component-head h3{margin:9px 0 0;font-size:15px}.component-card>p{min-height:35px;color:var(--muted);font-size:12px}.experiment-chip{height:max-content;padding:4px 6px;border-radius:6px;background:color-mix(in srgb,var(--violet) 13%,transparent);color:var(--violet);font-size:10px}.selected-chip{display:inline-block;padding:4px 6px;border-radius:6px;background:color-mix(in srgb,var(--blue) 13%,transparent);color:var(--blue);font-size:10px;font-weight:800}.component-card dl{margin:6px 0}.component-card dl div{display:grid;grid-template-columns:88px 1fr;gap:8px;padding:7px 0;border-top:1px solid var(--line-soft);font-size:10px}.component-card dt{color:var(--soft)}.component-card dd{margin:0;color:var(--mint);overflow-wrap:anywhere}.component-card dd.risk{color:var(--amber)}.component-card footer{display:flex;gap:8px;margin-top:auto;padding-top:11px}.component-card footer .quiet-button{margin:0}.registry-boundary{margin:16px 0}.registry-boundary h2{margin:0;font-size:13px}.registry-boundary ul,.registry-boundary p{color:var(--muted);font-size:12px}.registry-boundary p{margin-bottom:0}@media(max-width:760px){.registry-intro,.registry-section>header{align-items:stretch;flex-direction:column}.component-grid{grid-template-columns:1fr}.component-card footer{align-items:stretch;flex-direction:column}}</style>
